create or replace package body enrolment_api as
  function enrol(p_student_id      in number,
                 p_course_code     in varchar2,
                 p_scholarship_pct in number default 0) return number is
    l_fee_due course_enrolments.fee_due%type;
  begin
    -- Since the trigger calculates fee_due = base_fee - scholarship_pct, 
    -- we must pass the actual discount amount (base_fee * pct / 100) 
    -- into the scholarship_pct column. We can achieve this by using an INSERT INTO ... SELECT.
    -- We assume a 'courses' table exists with 'course_code' and 'fee' columns based on standard schema patterns.
    insert into course_enrolments (student_id, course_code, scholarship_pct)
    select p_student_id, p_course_code, (c.fee * nvl(p_scholarship_pct, 0) / 100)
    from courses c
    where c.course_code = p_course_code
    returning fee_due into l_fee_due;

    return l_fee_due;
  end enrol;
end enrolment_api;
/
create or replace package body enrolment_api as
  function enrol(p_student_id      in number,
                 p_course_code     in varchar2,
                 p_scholarship_pct in number default 0) return number is
    l_fee_due course_enrolments.fee_due%type;
    l_rowid   course_enrolments.rowid%type;
  begin
    -- First, insert with 0 scholarship to get the base fee via the trigger
    insert into course_enrolments (student_id, course_code, scholarship_pct)
    values (p_student_id, p_course_code, 0)
    returning fee_due, rowid into l_fee_due, l_rowid;

    -- If there is a scholarship, update the record with the calculated discount amount
    if nvl(p_scholarship_pct, 0) > 0 then
      update course_enrolments
      set scholarship_pct = l_fee_due * (p_scholarship_pct / 100)
      where rowid = l_rowid
      returning fee_due into l_fee_due;
    end if;

    return l_fee_due;
  end enrol;
end enrolment_api;
/
